(94, 'footer', '* { box-sizing: border-box; } body {margin: 0;}.hover-effect1 ul{padding-top:1px;}.hover-effect1 ul li{display:inline-block;}.hover-effect1 ul li a{font-size:30px;text-align:center;color:#fff;margin:0px 10px;line-height:50px;display:inline-block;width:50px;height:50px;background:#dc3545;-webkit-transition:all .6s ease;-moz-transition:all .6s ease;-ms-transition:all .6s ease;-o-transition:all .6s ease;transition:all .6s ease;}.hover-effect1 ul li:hover a{border-radius:50%;background:#dc3545;-moz-transform:rotate(360deg);-webkit-transform:rotate(360deg);-o-transform:rotate(360deg);-ms-transform:rotate(360deg);transform:rotate(360deg);}#iitg{width:100%;}*{box-sizing:border-box;}body{margin:0;}footer{color:#fff;}ul{padding:0px;}ol, ul{margin-bottom:0px;}.social-icon{padding:0;margin-bottom:0px;float:right;}.social-icon li{list-style:none;display:inline-block;}.social-icon li i{font-size:14px;color:#262725;border:solid 2px #ffffff;height:31px;width:31px;text-align:center;vertical-align:middle;border-radius:100px;line-height:27px;margin-right:15px;transition:1s;background:#fff;}.social-icon li i:hover{border:solid 2px #262725;color:#ffffff;background:#262725;}.phone-no i{position:relative;margin-right:14px;font-size:43px;top:5px;}.phone-no{margin-top:-22px;text-align:right;}.footer-day-time{padding-bottom:30px;border-bottom:2px solid #7a6f6f;padding-top:14px;margin-bottom:55px;}.footer-day-time ul li{display:inline;margin-right:20px;}.footer-day-time ul li:last-child{margin-right:0px;}.phone-no a{color:#fff;font-family:PlayfairDisplay-Black;font-size:34px;font-weight:bold;}.footer-top{background:#2f2f2f;padding:50px 0 50px;}.footer-top h4{font-size:19px;text-transform:uppercase;margin-bottom:30px;}.footer-top p{font-size:13px;line-height:2;}footer p{margin-bottom:0;}.address1 li{list-style:none;position:relative;padding:0px 0 14px 34px;line-height:26px;}ul.address1 span{position:absolute;width:40px;max-width:40px;left:0;}.address1 li a{color:#fff;text-decoration:none;}ul.address1 i{width:20px;position:absolute;left:0px;text-align:center;font-size:28px;top:0;}ul.address1 i.fa-envelope{font-size:18px;top:4px;}footer ul.social-icon{float:left;}footer .social-icon li i:hover{background:#4b8800;border-color:#4b8800;}.footer-bottom{background:#4b8800;padding:10px 0px;}.footer-bottom ul li{display:inline;margin-right:20px;font-size:18px;}.footer-bottom ul li a{color:#fff;}.footer-bottom ul{float:right;}.footer-bottom ul li:last-child{margin-right:0;}.copyright{font-size:18px;}#idbe{padding:0px 0px 0px 0px;}#iygj{padding:0px 0px 14px 34px;}#ieuj9{border:0px solid #b304dd;background-image:linear-gradient(#aa001a 0%, #aa001a 100%);}#i77uy{text-align:left;}#i6nmn{text-align:left;}#iq9um{text-align:left;}#iiipb{text-align:left;}#iwr2a{text-align:left;font-size:25px;}#io27z{text-align:left;color:#ff0000;}#ixtxr{text-align:left;color:#e30000;}#itsyu{padding:0px 0px 14px 0px;}#ig5ga{color:#fa0000;}#iy9zi{border:0px solid #ed0a00;}@media (max-width: 992px){#iwr2a{padding:0px 235px 0px 0px;}#i641n{padding:0px 0px 14px 0px;margin:34px 0px 0px 0px;}}@media (max-width: 480px){#i641n{padding:0px 0px 0px 0px;margin:34px 0px 0px 0px;}#iwr2a{padding:0px 0px 0px 0px;}}', '&lt;body id=&quot;iqw1&quot;&gt;&lt;div id=&quot;iitg&quot;&gt;&lt;!-- End of .container --&gt;&lt;/div&gt;&lt;div id=&quot;ib0p&quot;&gt;&lt;div id=&quot;i7c2&quot;&gt;&lt;footer id=&quot;idbe&quot;&gt;&lt;div id=&quot;iygj&quot; class=&quot;footer-top&quot;&gt;&lt;div class=&quot;container&quot;&gt;&lt;div class=&quot;footer-day-time&quot;&gt;&lt;div class=&quot;row&quot;&gt;&lt;div class=&quot;col-md-8&quot;&gt;&lt;ul&gt;&lt;li&gt;Opening Hours: Mon - Friday: 8AM - 5PM\n                  &lt;/li&gt;&lt;li&gt;Sunday: 8:00 AM - 12:00 PM\n                  &lt;/li&gt;&lt;/ul&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-4&quot;&gt;&lt;div id=&quot;itsyu&quot; class=&quot;phone-no&quot;&gt;&lt;a href=&quot;tel:+12 34 56 78 90&quot; id=&quot;iwr2a&quot;&gt;&lt;i aria-hidden=&quot