(241, 'footer', '* { box-sizing: border-box; } body {margin: 0;}.elementor-widget-social-icons.elementor-grid-0 .elementor-widget-container, .elementor-widget-social-icons.elementor-grid-mobile-0 .elementor-widget-container, .elementor-widget-social-icons.elementor-grid-tablet-0 .elementor-widget-container{line-height:1;font-size:0;}.elementor-widget-social-icons:not(.elementor-grid-0):not(.elementor-grid-tablet-0):not(.elementor-grid-mobile-0) .elementor-grid{display:inline-grid;}.elementor-widget-social-icons .elementor-grid{grid-column-gap:var(--grid-column-gap, 5px);grid-row-gap:var(--grid-row-gap, 5px);grid-template-columns:var(--grid-template-columns);justify-content:var(--justify-content, center);justify-items:var(--justify-content, center);}.elementor-icon.elementor-social-icon{font-size:var(--icon-size, 25px);line-height:var(--icon-size, 25px);width:calc(var(--icon-size, 25px) + (2 * var(--icon-padding, .5em)));height:calc(var(--icon-size, 25px) + (2 * var(--icon-padding, .5em)));}.elementor-social-icon{--e-social-icon-icon-color:#fff;display:inline-flex;background-color:#69727d;align-items:center;justify-content:center;text-align:center;cursor:pointer;}.elementor-social-icon i{color:var(--e-social-icon-icon-color);}.elementor-social-icon svg{fill:var(--e-social-icon-icon-color);}.elementor-social-icon:last-child{margin:0;}.elementor-social-icon:hover{opacity:.9;color:#fff;}.elementor-social-icon-facebook{background-color:#3b5998;}.elementor-social-icon-instagram{background-color:#262626;}.elementor-social-icon-twitter{background-color:#1da1f2;}.elementor-social-icon-whatsapp{background-color:#25d366;}.elementor-social-icon-youtube{background-color:#cd201f;}.elementor-shape-rounded .elementor-icon.elementor-social-icon{border-radius:10%;}.elementor-shape-circle .elementor-icon.elementor-social-icon{border-radius:50%;}*{box-sizing:border-box;}body{margin:0;}#i7ouo{color:#ffffff;}#iva8k6{color:#ffffff;}', '&lt;body id=&quot;ijus&quot;&gt;&lt;footer itemtype=&