(175, 304, '* { box-sizing: border-box; } body {margin: 0;}#main-wrapper{padding-bottom:0px;}#if6j{visibility:visible;}#izj2g{visibility:visible;}#imz4v{visibility:visible;animation-name:animateUpDown;}#iabdb{visibility:visible;animation-name:animateUpDown;}#imtrq{visibility:visible;animation-name:animateUpDown;}#iw13r{visibility:visible;animation-name:animateUpDown;}#i2buug{visibility:visible;}#is9igd{visibility:visible;}#ij6hhi{visibility:visible;}#i0p2xe{visibility:visible;}#ipk1af{visibility:visible;}#inc3d2{visibility:visible;}#il8t0g{visibility:visible;}#i4awo6{visibility:visible;}#is6a35{visibility:visible;}#ihlses{visibility:visible;}#i19wjj{background-image:url(&quot;assets/images/box-image/home-processing-software-image-01.webp&quot;);}#irak5e{background-image:url(&quot;assets/images/box-image/home-processing-software-image-02.webp&quot;);}#ibm9w7{background-image:url(&quot;assets/images/box-image/home-processing-software-image-03.webp&quot;);}#ibtb8q{background-image:url(&quot;assets/images/box-image/home-processing-software-image-04.webp&quot;);}#ipxg3j{background-image:url(&quot;assets/images/box-image/mitech-home-infotechno-box-large-image_02-330x330.webp&quot;);}#is8uzo{background-image:url(&quot;assets/images/box-image/mitech-home-infotechno-box-large-image_04-330x330.webp&quot;);}#inskp4{transform:translate3d(-372px, 0px, 0px);transition-duration:0ms;}#ifvaar{width:342px;margin-right:30px;}#idruoi{visibility:hidden;animation-name:none;}#igq7oc{width:342px;margin-right:30px;}#ijtdxn{visibility:visible;}#ikbrzh{width:342px;margin-right:30px;}#i8uwj2{visibility:visible;}#ioajha{width:342px;margin-right:30px;}#idxz6a{visibility:visible;}#intnzj{width:342px;margin-right:30px;}#iegphc{visibility:visible;}#idn2zf{width:342px;margin-right:30px;}#iso1dx{visibility:hidden;animation-name:none;}#i0jge3{transform:translate3d(-1116px, 0px, 0px);transition-duration:0ms;}#ik22p1{width:156px;margin-right:30px;}#i2zlif{width:156px;margin-right:30px;}#i5u9cx{width:156px;margin-right:30px;}#idm4ds{width:156px;margin-right:30px;}#ikibd8{width:156px;margin-right:30px;}#ikrr55{width:156px;margin-right:30px;}#i72auw{width:156px;margin-right:30px;}#imso01{width:156px;margin-right:30px;}#ixqtek{width:156px;margin-right:30px;}#iqur09{width:156px;margin-right:30px;}#i83y6h{width:156px;margin-right:30px;}#iifi5z{width:156px;margin-right:30px;}#iyh94l{width:156px;margin-right:30px;}', '&lt;body id=&quot;iv44&quot;&gt;&lt;div id=&quot;main-wrapper&quot;&gt;&lt;div class=&quot;site-wrapper-reveal&quot;&gt;&lt;!--============ Infotechno Hero Start ============--&gt;&lt;div class=&quot;processing-hero processing-hero-bg&quot;&gt;&lt;div class=&quot;container&quot;&gt;&lt;div class=&quot;row align-items-center&quot;&gt;&lt;!--baseline--&gt;&lt;div class=&quot;col-lg-8 col-md-7&quot;&gt;&lt;div class=&quot;processing-hero-text wow move-up animated&quot; id=&quot;if6j&quot;&gt;&lt;h6&gt;IT Software and design &lt;/h6&gt;&lt;h1 class=&quot;font-weight--reguler mb-15&quot;&gt;Virtual technology in a &lt;span class=&quot;text-color-secondary&quot;&gt;Refined IT System&lt;/span&gt;&lt;/h1&gt;&lt;p&gt;Set the trends for desktop &amp;amp; server virtualization technology&lt;/p&gt;&lt;div class=&quot;hero-button mt-30&quot;&gt;&lt;a href=&quot;#&quot; class=&quot;btn btn--secondary&quot;&gt;Free Sample&lt;/a&gt;&lt;div class=&quot;hero-popup-video video-popup&quot;&gt;&lt;a href=&quot;https://www.youtube.com/watch?v=vqZuSUtczbU&quot; class=&quot;video-link&quot;&gt;&lt;div class=&quot;video-content&quot;&gt;&lt;div class=&quot;video-play&quot;&gt;&lt;span class=&quot;video-play-icon&quot;&gt;&lt;i class=&quot;fa fa-play&quot;&gt;&lt;/i&gt;&lt;/span&gt;&lt;/div&gt;&lt;div class=&quot;video-text&quot;&gt; How we work&lt;/div&gt;&lt;/div&gt;&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-4 col-md-5&quot;&gt;&lt;div class=&quot;processing-hero-images-wrap wow move-up animated&quot; id=&quot;izj2g&quot;&gt;&lt;div class=&quot;processing-hero-images&quot;&gt;&lt;img src=&quot;assets/images/hero/slider-processing-slide-01-image-01.webp&quot; alt=&quot;&quot; class=&quot;img-fluid&quot;/&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;!--============ Infotechno Hero End ============--&gt;&lt;!--====================  Accordion area ====================--&gt;&lt;div class=&quot;accordion-wrapper section-space--ptb_100&quot;&gt;&lt;div class=&quot;container-fluid&quot;&gt;&lt;div class=&quot;row align-items-center&quot;&gt;&lt;div class=&quot;col-lg-6&quot;&gt;&lt;div class=&quot;faq-wrapper faq-custom-col&quot;&gt;&lt;div class=&quot;section-title section-space--mb_40&quot;&gt;&lt;h6 class=&quot;section-sub-title mb-20&quot;&gt;Our company&lt;/h6&gt;&lt;h3 class=&quot;heading&quot;&gt;Share the joy of achieving &lt;span class=&quot;text-color-primary&quot;&gt; glorious moments&lt;/span&gt; &amp;amp; climbed up the top.&lt;/h3&gt;&lt;/div&gt;&lt;div id=&quot;accordion&quot;&gt;&lt;div class=&quot;card&quot;&gt;&lt;div id=&quot;headingOne&quot; class=&quot;card-header&quot;&gt;&lt;h5 class=&quot;mb-0&quot;&gt;&lt;button type=&quot;button&quot; data-bs-toggle=&quot;collapse&quot; data-bs-target=&quot;#collapseOne&quot; aria-expanded=&quot;true&quot; aria-controls=&quot;collapseOne&quot; class=&quot;btn-link collapsed&quot;&gt;Send&lt;/button&gt;&lt;/h5&gt;&lt;/div&gt;&lt;div id=&quot;collapseOne&quot; aria-labelledby=&quot;headingOne&quot; data-bs-parent=&quot;#accordion&quot; class=&quot;collapse show&quot;&gt;&lt;div class=&quot;card-body&quot;&gt;&lt;p&gt;Through the collaboration with customers in discussing needs and demand, we&#039;re able to attain mutual understanding, gain customer trust to offer appropriate advice, and bring about suggestions on suitable technology to transform your business. &lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;card&quot;&gt;&lt;div id=&quot;headingTwo&quot; class=&quot;card-header&quot;&gt;&lt;h5 class=&quot;mb-0&quot;&gt;&lt;button type=&quot;button&quot; data-bs-toggle=&quot;collapse&quot; data-bs-target=&quot;#collapseTwo&quot; aria-expanded=&quot;false&quot; aria-controls=&quot;collapseTwo&quot; class=&quot;btn-link collapsed&quot;&gt;Send&lt;/button&gt;&lt;/h5&gt;&lt;/div&gt;&lt;div id=&quot;collapseTwo&quot; aria-labelledby=&quot;headingTwo&quot; data-bs-parent=&quot;#accordion&quot; class=&quot;collapse&quot;&gt;&lt;div class=&quot;card-body&quot;&gt;&lt;p&gt;Mitech takes into consideration every little detail to make sure the system run smoothly and responsively. Mitech employs a new technique called Minified Technology for securing customers&#039; database &amp;amp; building up highly confidential firewalls. &lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;card&quot;&gt;&lt;div id=&quot;headingThree&quot; class=&quot;card-header&quot;&gt;&lt;h5 class=&quot;mb-0&quot;&gt;&lt;button type=&quot;button&quot; data-bs-toggle=&quot;collapse&quot; data-bs-target=&quot;#collapseThree&quot; aria-expanded=&quot;false&quot; aria-controls=&quot;collapseThree&quot; class=&quot;btn-link collapsed&quot;&gt;Send&lt;/button&gt;&lt;/h5&gt;&lt;/div&gt;&lt;div id=&quot;collapseThree&quot; aria-labelledby=&quot;headingThree&quot; data-bs-parent=&quot;#accordion&quot; class=&quot;collapse&quot;&gt;&lt;div class=&quot;card-body&quot;&gt;&lt;p&gt;We reduce redundant complex calculations and lengthy erroneous code texts with simpler ones to ensure Mitech would run seamlessly and the design is reserved in its best form when viewed from a wide range of mobile devices &amp;amp; browsers. &lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-6&quot;&gt;&lt;div class=&quot;rv-video-section&quot;&gt;&lt;div class=&quot;ht-banner-01&quot;&gt;&lt;img src=&quot;assets/images/banners/home-processing-video-intro-slider-slide-01-image-02.webp&quot; alt=&quot;&quot; id=&quot;imz4v&quot; class=&quot;img-fluid border-radus-5