(217, 365, '* { box-sizing: border-box; } body {margin: 0;}*{box-sizing:border-box;}body{margin:0;width:100%;font-family:&quot;Oswald&quot;, sans-serif;font-size:12pt;font-weight:400;}section{padding:60px 0;min-height:100vh;}a, a:hover, a:focus, a:active{text-decoration:none;outline:none;}ul{margin:0;padding:0;list-style:none;}.bg-gray{background-color:#f9f9f9;}.site-heading h2{display:block;font-weight:700;margin-bottom:10px;text-transform:uppercase;}.site-heading h2 span{color:#00a01d;}.site-heading h4{display:inline-block;padding-bottom:20px;position:relative;text-transform:capitalize;z-index:1;}.site-heading h4::before{background:#00a01d none repeat scroll 0 0;bottom:0;content:&quot;&quot;;height:2px;left:50%;margin-left:-25px;position:absolute;width:50px;}.site-heading{margin-bottom:60px;overflow:hidden;margin-top:-5px;}.carousel-shadow .owl-stage-outer{margin:-15px -15px 0;padding:15px;}.we-offer-area .our-offer-carousel .owl-dots .owl-dot span{background:#ffffff none repeat scroll 0 0;border:2px solid;height:15px;margin:0 5px;width:15px;}.we-offer-area .our-offer-carousel .owl-dots .owl-dot.active span{background:#00a01d none repeat scroll 0 0;border-color:#00a01d;}.we-offer-area .item{background:#ffffff none repeat scroll 0 0;border-left:2px solid #00a01d;-moz-box-shadow:0 0 10px #cccccc;-webkit-box-shadow:0 0 10px #cccccc;-o-box-shadow:0 0 10px #cccccc;box-shadow:0 0 10px #cccccc;overflow:hidden;padding:30px;position:relative;z-index:1;}.we-offer-area.text-center .item{background:#ffffff none repeat scroll 0 0;border:medium none;padding:67px 40px 64px;}.we-offer-area.text-center .item i{background:#00a01d none repeat scroll 0 0;-webkit-border-radius:50%;-moz-border-radius:50%;border-radius:50%;color:#ffffff;font-size:40px;height:80px;line-height:80px;position:relative;text-align:center;width:80px;z-index:1;transition:all 0.35s ease-in-out;-webkit-transition:all 0.35s ease-in-out;-moz-transition:all 0.35s ease-in-out;-ms-transition:all 0.35s ease-in-out;-o-transition:all 0.35s ease-in-out;margin-bottom:25px;}.we-offer-area.text-center .item i::after{border:2px solid #00a01d;-webkit-border-radius:50%;-moz-border-radius:50%;border-radius:50%;content:&quot;&quot;;height:90px;left:-5px;position:absolute;top:-5px;width:90px;z-index:-1;transition:all 0.35s ease-in-out;-webkit-transition:all 0.35s ease-in-out;-moz-transition:all 0.35s ease-in-out;-ms-transition:all 0.35s ease-in-out;-o-transition:all 0.35s ease-in-out;}.we-offer-area.item-border-less .item{border:medium none;}.we-offer-area .our-offer-items.less-carousel .equal-height{margin-bottom:30px;}.we-offer-area.item-border-less .item .number{font-family:&quot;Poppins&quot;,sans-serif;font-size:50px;font-weight:900;opacity:0.1;position:absolute;right:30px;top:30px;}.our-offer-carousel.center-active .owl-item:nth-child(2n) .item, .we-offer-area.center-active .single-item:nth-child(2n) .item{background:#00a01d none repeat scroll 0 0;}.our-offer-carousel.center-active .owl-item:nth-child(2n) .item i, .our-offer-carousel.center-active .owl-item:nth-child(2n) .item h4, .our-offer-carousel.center-active .owl-item:nth-child(2n) .item p, .we-offer-area.center-active .single-item:nth-child(2n) .item i, .we-offer-area.center-active .single-item:nth-child(2n) .item h4, .we-offer-area.center-active .single-item:nth-child(2n) .item p{color:#ffffff;}.we-offer-area .item i{color:#00a01d;display:inline-block;font-size:60px;margin-bottom:20px;}.we-offer-area .item h4{font-weight:600;text-transform:capitalize;}.we-offer-area .item p{margin:0;}.we-offer-area .item i, .we-offer-area .item h4, .we-offer-area .item p{transition:all 0.35s ease-in-out;-webkit-transition:all 0.35s ease-in-out;-moz-transition:all 0.35s ease-in-out;-ms-transition:all 0.35s ease-in-out;-o-transition:all 0.35s ease-in-out;}.we-offer-area .item::after{background:#00a01d none repeat scroll 0 0;content:&quot;&quot;;height:100%;left:-100%;position:absolute;top:0;transition:all 0.35s ease-in-out;-webkit-transition:all 0.35s ease-in-out;-moz-transition:all 0.35s ease-in-out;-ms-transition:all 0.35s ease-in-out;-o-transition:all 0.35s ease-in-out;width:100%;z-index:-1;}.we-offer-area .item:hover::after{left:0;}.we-offer-area .item:hover i, .we-offer-area .item:hover h4, .we-offer-area .item:hover p{color:#ffffff !important;}.we-offer-area.text-center .item:hover i::after{border-color:#ffffff !important;}.we-offer-area.text-center .item:hover i{background-color:#ffffff !important;color:#00a01d !important;}.we-offer-area.text-left .item i{background:#00a01d none repeat scroll 0 0;-webkit-border-radius:50%;-moz-border-radius:50%;border-radius:50%;color:#ffffff;display:inline-block;font-size:60px;height:100px;line-height:100px;margin-bottom:30px;position:relative;width:100px;z-index:1;text-align:center;}.we-offer-area.text-left .item i::after{border:2px solid #00a01d;-webkit-border-radius:50%;-moz-border-radius:50%;border-radius:50%;content:&quot;&quot;;height:120px;left:-10px;position:absolute;top:-10px;width:120px;}.grey-bg{background-color:#F5F7FA;}#ia510i{height:7px;}#i0h30f{width:80%;}#izjw1u{height:7px;}#in0r3d{width:35%;}#igoibq{height:7px;}#ii9t2z{width:60%;}#ic8xr7{height:7px;}#ixk4fb{width:40%;}p, a, h1, h2, h3, h4, h5, h6, ul, li{margin:0;padding:0;}.section-services{font-family:&quot;Poppins&quot;, sans-serif;background-color:#e6edf7;color:#202020;padding-top:115px;padding-bottom:120px;}.section-services .header-section{margin-bottom:34px;}.section-services .header-section .title{position:relative;padding-bottom:14px;margin-bottom:25px;font-weight:700;font-size:32px;}.section-services .header-section .title:before{content:&quot;&quot;;position:absolute;bottom:0;left:50%;transform:translateX(-50%);width:50px;height:3px;background-color:#ff4500;border-radius:3px;}.section-services .header-section .title:after{content:&quot;&quot;;position:absolute;bottom:0;left:50%;transform:translateX(30px);width:10px;height:3px;background-color:#504f93;border-radius:3px;}.section-services .header-section .description{font-size:14px;color:#282828;}.section-services .single-service{position:relative;margin-top:30px;background-color:#fff;border-radius:10px;padding:40px 30px;overflow:hidden;}.section-services .single-service .content{position:relative;z-index:20;}.section-services .single-service .circle-before{position:absolute;top:0;right:0px;transform:translate(40%, -40%);width:150px;height:150px;background-color:#ff4500;border:6px solid #504f93;border-radius:50%;opacity:0.5;z-index:10;transition:all .6s;}.section-services .single-service:hover .circle-before{width:100%;height:100%;transform:none;border:0;border-radius:0;opacity:1;}.section-services .single-service .icon{display:inline-block;margin-bottom:26px;width:70px;height:70px;background-color:#ff4500;border-radius:5px;line-height:70px;text-align:center;color:#fff;font-size:30px;transition:all .3s;}.section-services .single-service:hover .icon{background-color:#fff;color:#ff4500;}.section-services .single-service .title{margin-bottom:18px;font-weight:700;font-size:23px;transition:color .3s;}.section-services .single-service:hover .title{color:#fff;}.section-services .single-service .description{margin-bottom:20px;font-size:14px;transition:color .3s;}.section-services .single-service:hover .description{color:#fff;}.section-services .single-service a{position:relative;font-size:18px;color:#202020;text-decoration:none;font-weight:500;transition:color .3s;}.section-services .single-service:hover a{color:#fff;}.section-services .single-service a:after{content:&quot;&quot;;position:absolute;bottom:0;left:0;right:0;height:1px;background-color:#ff4500;transition:background-color .3s;}.section-services .single-service:hover a:after{background-color:#fff;}body, html{overflow-x:hidden;}h1, h2, h3, h4, h5, h6{font-family:&quot;Bebas Neue&quot;, cursive;}a{text-decoration:none;transition:all 0.5s ease-in-out;}a:hover{transition:all 0.5s ease-in-out;}.we-are-block{display:flex;flex-direction:column;align-items