row{flex-wrap:wrap;}}@media (max-width: 767px){.contact-detail span{width:auto;}.contact-detail span a{font-size:18px;padding:5px 10px;color:#000;border-radius:50%;margin:0px 5px 20px;}}@media (max-width: 575px){.contact-sec .contact-ul i{border:none;}}@media (max-width: 480px){.contact-sec .contact-ul li, .contact-ul b{font-size:16px;}}', '&lt;section class=&quot;about_section&quot;&gt;&lt;div class=&quot;container-fluid&quot;&gt;&lt;/div&gt;&lt;/section&gt;&lt;!-- end about section --&gt;&lt;!-- client section --&gt;&lt;!-- end client section --&gt;&lt;!-- contact section --&gt;&lt;img id=&quot;iu3f9i&quot; draggable=&quot;true&quot; src=&quot;https://test.webfire.in/public/temp/2/contact-banner.jpg&quot; class=&quot;gjs-selected&quot;/&gt;&lt;div class=&quot;row&quot; id=&quot;i3ebx&quot;&gt;&lt;div class=&quot;cell&quot; id=&quot;imw0s&quot;&gt;&lt;div id=&quot;idemm&quot;&gt;[ab-form id=230]	&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;cell&quot; id=&quot;ikaez&quot;&gt;&lt;iframe frameborder=&quot;0&quot; src=&quot;https://maps.google.com/maps?&amp;q=Firozabad Uttar Pradesh&amp;z=7&amp;t=w&amp;output=embed&quot; class=&quot;gjs-no-pointer&quot; id=&quot;iusjp&quot;&gt;&lt;/iframe&gt;&lt;/div&gt;&lt;/div&gt;&lt;!-- end contact section --&gt;&lt;!-- info section --&gt;&lt;!-- end info_section --&gt;', 34, '1', '2024-02-16 07:13:40', '2024-04-07 08:38:25');
