(243, 391, '* { box-sizing: border-box; } body {margin: 0;}*{box-sizing:border-box;margin:0;padding:0;font-family:Exo;}body{margin:0;}#igj42k{margin:100px 0px 0px 0px;}#ieiv{width:468px;height:359px;margin:0px 0px 0px 57px;}#iu5y9{color:#f10000;font-size:30px;}a, a:hover, a:focus, a:active{text-decoration:none;outline:none;}a, a:active, a:focus{color:#333;text-decoration:none;transition-timing-function:ease-in-out;-ms-transition-timing-function:ease-in-out;-moz-transition-timing-function:ease-in-out;-webkit-transition-timing-function:ease-in-out;-o-transition-timing-function:ease-in-out;transition-duration:.2s;-ms-transition-duration:.2s;-moz-transition-duration:.2s;-webkit-transition-duration:.2s;-o-transition-duration:.2s;}ul{margin:0;padding:0;list-style:none;}img{max-width:100%;height:auto;}span, a, a:hover{display:inline-block;text-decoration:none;color:inherit;}.section-head{margin-bottom:60px;}.section-head h4{position:relative;padding:0;color:#f91942;line-height:1;letter-spacing:0.3px;font-size:34px;font-weight:700;text-align:center;text-transform:none;margin-bottom:30px;}.section-head h4:before{content:&#039;&#039;;width:60px;height:3px;background:#f91942;position:absolute;left:0px;bottom:-10px;right:0;margin:0 auto;}.section-head h4 span{font-weight:700;padding-bottom:5px;color:#2f2f2f;}p.service_text{color:#cccccc !important;font-size:16px;line-height:28px;text-align:center;}.section-head p, p.awesome_line{color:#818181;font-size:16px;line-height:28px;text-align:center;}.extra-text span{font-weight:700;color:#f91942;}.item{background:#fff;text-align:center;padding:30px 25px;-webkit-box-shadow:0 0px 25px rgba(0, 0, 0, 0.07);box-shadow:0 0px 25px rgba(0, 0, 0, 0.07);border-radius:20px;border:5px solid rgba(0, 0, 0, 0.07);margin-bottom:30px;-webkit-transition:all .5s ease 0;transition:all 0.5s ease 0s;}.item:hover{background:#f91942;box-shadow:0 8px 20px 0px rgba(0, 0, 0, 0.2);-webkit-transition:all .5s ease 0;transition:all 0.5s ease 0s;}.item:hover .item, .item:hover span.icon{background:#fff;border-radius:10px;-webkit-transition:all .5s ease 0;transition:all 0.5s ease 0s;}.item:hover h6, .item:hover p{color:#fff;-webkit-transition:all .5s ease 0;transition:all 0.5s ease 0s;}.item .icon{font-size:40px;margin-bottom:25px;color:#f91942;width:90px;height:90px;line-height:96px;border-radius:50px;}.item .feature_box_col_one{background:rgba(247, 198, 5, 0.20);color:#f91942;}.item .feature_box_col_two{background:rgba(255, 77, 28, 0.15);color:#f91942;}.item .feature_box_col_three{background:rgba(0, 147, 38, 0.15);color:#f91942;}.item .feature_box_col_four{background:rgba(0, 108, 255, 0.15);color:#f91942;}.item .feature_box_col_five{background:rgba(146, 39, 255, 0.15);color:#f91942;}.item .feature_box_col_six{background:rgba(23, 39, 246, 0.15);color:#f91942;}.item p{font-size:15px;line-height:26px;}.item h6{margin-bottom:20px;color:#2f2f2f;}.mission p{margin-bottom:10px;font-size:15px;line-height:28px;font-weight:500;}.mission i{display:inline-block;width:50px;height:50px;line-height:50px;text-align:center;background:#f91942;border-radius:50%;color:#fff;font-size:25px;}.mission .small-text{margin-left:10px;font-size:13px;color:#666;}.skills .prog-item{margin-bottom:25px;}.skills .prog-item:last-child{margin-bottom:0;}.skills .prog-item p{font-weight:500;font-size:15px;margin-bottom:10px;}.skills .prog-item .skills-progress{width:100%;height:10px;background:#e0e0e0;border-radius:20px;position:relative;}.skills .prog-item .skills-progress span{position:absolute;left:0;top:0;height:100%;background:#f91942;width:10%;border-radius:10px;-webkit-transition:all 1s;transition:all 1s;}.skills .prog-item .skills-progress span:after{content:attr(data-value);position:absolute;top:-5px;right:0;font-size:10px;font-weight:600;color:#fff;background:rgba(0, 0, 0, 0.9);padding:3px 7px;border-radius:30px;}.profile-card .img{position:relative;width:100%;height:100%;transition:.6s;z-index:99;}.profile-card:hover .img{transform:translateY(-60px);}.img img{width:100%;border-radius:50%;box-shadow:0 0 22px #3336;transition:.6s;}.profile-card:hover img{border-radius:10px;}.profile-card:hover .caption{opacity:1;}.caption h3{font-size:21px;font-family:sans-serif;}.caption p{font-size:15px;color:#0c52a1;font-family:sans-serif;margin:2px 0 9px 0;}.caption .social-links a{color:#333;margin-right:15px;font-size:21px;transition:.6s;}.social-links a:hover{color:#0c52a1;}#im226{font-size:20px;color:#000000;}a, p, h1, h2, h3, h4, ul{margin:0;padding:0;}.section-services{padding-top:110px;padding-bottom:120px;font-family:&quot;Poppins&quot;, sans-serif;background-color:#211f24;color:#fff;}.section-services .header-section{margin-bottom:35px;}.section-services .header-section .title{position:relative;margin-bottom:40px;padding-bottom:25px;text-transform:uppercase;font-weight:700;}.section-services .header-section .title:before{content:&quot;&quot;;position:absolute;bottom:0;left:50%;transform:translateX(-50%);width:140px;height:1px;background-color:#f70037;}.section-services .header-section .title:after{content:&quot;&quot;;position:absolute;bottom:-1px;left:50%;transform:translateX(-50%);width:45px;height:3px;background-color:#f70037;}.section-services .header-section .title span{color:#f70037;}.section-services .header-section .description{color:#6f6f71;}.section-services .single-service{margin-top:40px;background-color:#24252a;box-shadow:0 0 10px 0 rgba(0,0,0,.1);}.section-services .single-service .part-1{padding:40px 40px 25px;border-bottom:2px solid #1d1e23;}.section-services .single-service .part-1 i{margin-bottom:25px;font-size:50px;color:#f70037;}.section-services .single-service .part-1 .title{font-size:17px;font-weight:700;letter-spacing:0.02em;line-height:1.8em;}.section-services .single-service .part-2{padding:30px 40px 40px;}.section-services .single-service .part-2 .description{margin-bottom:22px;color:#6f6f71;font-size:14px;line-height:1.8em;}.section-services .single-service .part-2 a{color:#fff;font-size:14px;text-decoration:none;}.section-services .single-service .part-2 a i{margin-right:10px;color:#f70037;}#inyoqq{color:#ffffff;}#i1fyso{color:#ffffff;}#i9ooaz{color:#ffffff;}#i6m8jd{color:#fdfdfd;}#irotyx{color:#ffffff;}#if9omx{color:#fffdfe;}#ijn5ux{color:#fdf9fa;}#iy7msh{color:#ffffff;}#iwt4eg{visibility:visible;}#ihtd44{visibility:visible;}#ig29ci{visibility:visible;}#ie9a9e{visibility:visible;}@font-face{font-family:Exo;src:url(./fonts/Exo2.0-Medium.otf);}@media (max-width: 992px){#ieiv{width:100%;height:276px;margin:0px 0px 0px 0px;}}@media (max-width: 480px){#ieiv{width:100%;height:207px;top:100px;left:15px;margin:0px 0px 0px 0px;}#iu5y9{font-size:25px;font-family:Georgia, serif;margin:19px 15px 0px 0px;}}', '&lt;div id=&quot;ih3cr9&quot;&gt;[AB-Slider id=213]&lt;/div&gt;&lt;div id=&quot;iv68&quot;&gt;&lt;!-- end offer section --&gt;&lt;!-- about section --&gt;&lt;section class=&quot;about_section&quot;&gt;&lt;div id=&quot;iozz&quot; class=&quot;container-fluid&quot;&gt;&lt;div id=&quot;igj42k&quot; class=&quot;row&quot;&gt;&lt;div class=&quot;col-md-6&quot;&gt;&lt;div id=&quot;iriql&quot; class=&quot;img-box&quot;&gt;&lt;img src=&quot;https://test.webfire.in/public/temp/2/Assethome1.png&quot; alt=&quot;&quot; id=&quot;ieiv&quot;/&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;col-md-5 col-lg-4&quot;&gt;&lt;div id=&quot;irf15&quot; class=&quot;detail-box&quot;&gt;&lt;div class=&quot;heading_container&quot;&gt;&lt;h2 id=&quot;iu5y9&quot;&gt;About Apna College&lt;/h2&gt;&lt;/div&gt;&lt;p id=&quot;im226&quot;&gt;At Apna College, we believe in empowering students to reach their fullest potential through a transformative educational experience. Established in [year], Apna College has been dedicated to providing high-quality education that combines academic excellence with practical skills and personal growth.\n            &lt;/p&gt;&lt;div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/section&gt;&lt;!-- end about section --&gt;&lt;!-- client section --&gt;&lt;div id=&quot;iwau8&quot;&gt;&lt;div class=&quot;feat bg-gray pt-5 pb-5&quot;&gt;&lt;div class=&quot;container&quot;&gt;&lt;div class=&quot;row&quot;&gt;&lt;div class=&quot;section-head col-sm-12&quot;&gt;&lt;h4&gt;&lt;span&gt;Why Choose&lt;/span&gt; Us?&lt;/h4&gt;&lt;p&gt;When you choose us, you&#039;ll feel the benefit of 10 years&#039; experience of Web Development. Because we know the digital world and we know that how to handle it. With working knowledge of online, SEO and social media.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-4 col-sm-6&quot;&gt;&lt;div class=&quot;item&quot;&gt; &lt;span class=&quot;icon feature_box_col_one&quot;&gt;&lt;i class=&quot;fa fa-globe&quot;&gt;&lt;/i&gt;&lt;/span&gt;&lt;h6&gt;Modern Design&lt;/h6&gt;&lt;p&gt;We use latest technology for the latest world because we know the demand of peoples.&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-4 col-sm-6&quot;&gt;&lt;div class=&quot;item&quot;&gt; &lt;span class=&quot;icon feature_box_col_two&quot;&gt;&lt;i class=&quot;fa fa-anchor&quot;&gt;&lt;/i&gt;&lt;/span&gt;&lt;h6&gt;Creative Design&lt;/h6&gt;&lt;p&gt;We are always creative and and always lisen our costomers and we mix these two things and make beast design.&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-4 col-sm-6&quot;&gt;&lt;div class=&quot;item&quot;&gt; &lt;span class=&quot;icon feature_box_col_three&quot;&gt;&lt;i class=&quot;fa fa-hourglass-half&quot;&gt;&lt;/i&gt;&lt;/span&gt;&lt;h6&gt;24 x 7 User Support&lt;/h6&gt;&lt;p&gt;If our customer has any problem and any query we are always happy to help then.&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-4 col-sm-6&quot;&gt;&lt;div class=&quot;item&quot;&gt; &lt;span class=&quot;icon feature_box_col_four&quot;&gt;&lt;i class=&quot;fa fa-database&quot;&gt;&lt;/i&gt;&lt;/span&gt;&lt;h6&gt;Business Growth&lt;/h6&gt;&lt;p&gt;Everyone wants to live on top of the mountain, but all the happiness and growth occurs while you&#039;re climbing it&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-4 col-sm-6&quot;&gt;&lt;div class=&quot;item&quot;&gt; &lt;span class=&quot;icon feature_box_col_five&quot;&gt;&lt;i class=&quot;fa fa-upload&quot;&gt;&lt;/i&gt;&lt;/span&gt;&lt;h6&gt;Market Strategy&lt;/h6&gt;&lt;p&gt;Holding back technology to preserve broken business models is like allowing blacksmiths to veto the internal combustion engine in order to protect their horseshoes.&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-4 col-sm-6&quot;&gt;&lt;div class=&quot;item&quot;&gt; &lt;span class=&quot;icon feature_box_col_six&quot;&gt;&lt;i class=&quot;fa fa-camera&quot;&gt;&lt;/i&gt;&lt;/span&gt;&lt;h6&gt;Affordable cost&lt;/h6&gt;&lt;p&gt;Love is a special word, and I use it only when I mean it. You say the word too much and it becomes cheap.&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;section id=&quot;i8rh4e&quot; class=&quot;client_section layout_padding&quot;&gt;&lt;div id=&quot;ikva1g&quot;&gt;[AB-Gallery id=217]&lt;/div&gt;&lt;/section&gt;&lt;div id=&quot;igpfeo&quot;&gt;&lt;meta charset=&quot;utf-8&quot;/&gt;&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;/&gt;&lt;title&gt;Services Section Using Bootstrap 4&lt;/title&gt;&lt;link rel=&quot;stylesheet&quot; href=&quot;https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.11.2/css/all.min.css&quot;/&gt;&lt;link rel=&quot;stylesheet&quot; href=&quot;https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.11.2/css/fontawesome.min.css&quot;/&gt;&lt;link rel=&quot;stylesheet&quot; href=&quot;https://cdnjs.cloudflare.com/ajax/libs/twitter-bootstrap/4.4.1/css/bootstrap.css&quot;/&gt;&lt;link href=&quot;https://fonts.googleapis.com/css?family=Poppins:500,700&amp;display=swap&quot; rel=&quot;stylesheet&quot;/&gt;&lt;section class=&quot;section-services&quot;&gt;&lt;div class=&quot;container&quot;&gt;&lt;div class=&quot;row justify-content-center text-c